SELECT *, ROUND(salary / SUM(salary) OVER (PARTITION BY manager_id), 4) AS salary_share, AVG(salary) OVER w_ordered AS salary_avg_3, FIRST_VALUE(job_title, TRUE) OVER w_ordered_2 AS first_known_job_title, RANK() OVER (PARTITION BY manager_id ORDER BY salary DESC) AS salary_rank, ROUND(salary / SUM(salary) OVER (PARTITION BY manager_id), 4) AS salary_share_2 FROM employees WINDOW w_ordered AS (PARTITION BY dept_id ORDER BY salary, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW), w_ordered_2 AS (PARTITION BY manager_id ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
